/**
 * Where the video of `video/embed` comes from, and how it is embedded once the visitor presses play
 * (t-2026-10-12-33). Pure, no I/O: the props parser, the component and the tests share it.
 *
 * A link is read with a strict allow-list per host: the host is one of the provider's own, the path is
 * the video's own page or embed address, and the id has the provider's shape. Anything else is refused,
 * so a template cannot frame another site. The embed is the provider's official player address:
 * `youtube-nocookie.com` for YouTube, `vk.com/video_ext.php` for VK Video, `rutube.ru/play/embed` for
 * Rutube.
 */

export type VideoSource = { url: string } | { file: string }

export type VideoProvider = "youtube" | "vk" | "rutube"

/** What the player draws after the press: a provider's frame, or the template's own file. */
export type VideoMedia =
  | { kind: "frame"; provider: VideoProvider; src: string }
  | { kind: "file"; src: string; loop: boolean; muted: boolean }

/** `/templates/<template-id>/<file>.(mp4|webm)`, a clip committed with its template, as `ImageRef`'s `src`. */
export const TEMPLATE_VIDEO = /^\/templates\/[a-z0-9]+(?:-[a-z0-9]+)*\/[a-z0-9][a-z0-9_-]*(?:\.[a-z0-9_-]+)*\.(?:mp4|webm)$/

const YOUTUBE_HOSTS = new Set([
  "youtube.com",
  "www.youtube.com",
  "m.youtube.com",
  "youtu.be",
  "youtube-nocookie.com",
  "www.youtube-nocookie.com",
])
const VK_HOSTS = new Set(["vk.com", "www.vk.com", "m.vk.com", "vk.ru", "www.vk.ru", "m.vk.ru", "vkvideo.ru", "www.vkvideo.ru", "m.vkvideo.ru"])
const RUTUBE_HOSTS = new Set(["rutube.ru", "www.rutube.ru"])

const YOUTUBE_ID = /^[A-Za-z0-9_-]{11}$/
const VK_OWNER = /^-?\d{1,20}$/
const VK_ID = /^\d{1,20}$/
const VK_HASH = /^[0-9a-f]{1,32}$/
const RUTUBE_ID = /^[0-9a-f]{32}$/
const RUTUBE_KEY = /^[A-Za-z0-9_-]{1,64}$/

const youtube = (id: string) => `https://www.youtube-nocookie.com/embed/${id}?autoplay=1&rel=0&playsinline=1`

function readYoutube(url: URL): string | null {
  const segments = url.pathname.split("/").filter(Boolean)
  let id: string | null | undefined = null
  if (url.hostname === "youtu.be") id = segments.length === 1 ? segments[0] : null
  else if (url.pathname === "/watch") id = url.searchParams.get("v")
  else if (segments.length === 2 && ["embed", "shorts", "live"].includes(segments[0])) id = segments[1]
  return id && YOUTUBE_ID.test(id) ? youtube(id) : null
}

function readVk(url: URL): string | null {
  let owner: string | null = null
  let id: string | null = null
  let hash: string | null = null
  const page = url.pathname.match(/^\/video(-?\d{1,20})_(\d{1,20})\/?$/)
  if (page) {
    ;[, owner, id] = page
  } else if (url.pathname === "/video_ext.php") {
    owner = url.searchParams.get("oid")
    id = url.searchParams.get("id")
    hash = url.searchParams.get("hash")
  }
  if (!owner || !id || !VK_OWNER.test(owner) || !VK_ID.test(id)) return null
  if (hash !== null && !VK_HASH.test(hash)) return null
  return `https://vk.com/video_ext.php?oid=${owner}&id=${id}${hash ? `&hash=${hash}` : ""}&autoplay=1`
}

function readRutube(url: URL): string | null {
  const page = url.pathname.match(/^\/(?:video|shorts)\/([^/]+)\/?$/) ?? url.pathname.match(/^\/play\/embed\/([^/]+)\/?$/)
  const id = page?.[1]
  const key = url.searchParams.get("p")
  if (!id || !RUTUBE_ID.test(id)) return null
  if (key !== null && !RUTUBE_KEY.test(key)) return null
  return `https://rutube.ru/play/embed/${id}${key ? `?p=${key}` : ""}`
}

/** A link's provider and its embed address, or null when the link is not one the block takes. */
export function parseVideoUrl(value: string): { provider: VideoProvider; embed: string } | null {
  if (value.length > 2048 || /\s/.test(value)) return null
  let url: URL
  try {
    url = new URL(value)
  } catch {
    return null
  }
  if (url.protocol !== "https:" || url.username || url.password || url.port) return null
  const host = url.hostname
  const read: [VideoProvider, string | null] | null = YOUTUBE_HOSTS.has(host)
    ? ["youtube", readYoutube(url)]
    : VK_HOSTS.has(host)
      ? ["vk", readVk(url)]
      : RUTUBE_HOSTS.has(host)
        ? ["rutube", readRutube(url)]
        : null
  return read && read[1] ? { provider: read[0], embed: read[1] } : null
}

/** What the player draws for a parsed source: null when a link is not one the block takes. */
export function mediaOf(source: VideoSource, { loop, muted }: { loop: boolean; muted: boolean }): VideoMedia | null {
  if ("file" in source) {
    return TEMPLATE_VIDEO.test(source.file) ? { kind: "file", src: source.file, loop, muted } : null
  }
  const parsed = parseVideoUrl(source.url)
  return parsed ? { kind: "frame", provider: parsed.provider, src: parsed.embed } : null
}
